//! Output parity between `voxr_narrate` and two pieces of the JavaScript
//! narration skill: `review` and the engine choice at the top of `speak()`.
//!
//! The review fixture (`tests/fixtures/narration_review_oracle.json`) is
//! checked in and was generated by
//! `tests/tools/narration_oracle/review.mjs` over the corpus beside it.
//! `review` is exported as is and reads no machine state, so the oracle
//! runs it directly.
//!
//! The engine-choice fixture
//! (`tests/fixtures/narration_engine_choice_oracle.json`) was generated by
//! `tests/tools/narration_oracle/engine_choice.mjs`, which runs a patched
//! copy of `speak.mjs` that lets the oracle fix the user's config and
//! VoxCPM2's readiness, and that stops `speak()` right before it runs an
//! engine, capturing the branch it chose.

use std::path::Path;

use serde::Deserialize;
use serde_json::Value;
use voxr_narrate::{
    DefaultEngineOpts, Engine, EngineChoice, Error, ReviewOptions, SpeakOpts, TtsConfig,
    default_engine, resolve_speak, review,
};

mod common;
use common::{assert_oracle_current, load_json};

const REVIEW_FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_review_oracle.json"
);
const REVIEW_ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/review.mjs"
);
const ENGINE_FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_engine_choice_oracle.json"
);
const ENGINE_ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/engine_choice.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    cases: Vec<Value>,
}

fn text<'a>(v: &'a Value, field: &str) -> Option<&'a str> {
    v[field].as_str()
}

fn reason(e: Error) -> String {
    match e {
        Error::InvalidArgument { reason, .. }
        | Error::DataError { reason }
        | Error::Pattern { reason }
        | Error::Recognizer { reason }
        | Error::File { reason } => reason,
    }
}

// ---- review ----

fn review_options(opts: &Value) -> ReviewOptions<'_> {
    ReviewOptions {
        language: text(opts, "language"),
        notes: opts["notes"].as_bool().unwrap_or(false),
    }
}

fn check_review_case(case: &Value) {
    let file = text(case, "file").unwrap_or_else(|| panic!("case {case} has no file"));
    let script = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/tools/narration_oracle/corpus")
            .join(file),
    )
    .unwrap_or_else(|e| panic!("reading corpus file {file}: {e}"));
    let options = review_options(&case["options"]);
    let got = review(&script, &options).unwrap_or_else(|e| panic!("review({file}): {e}"));
    let got_json = serde_json::to_value(&got).unwrap_or_else(|e| panic!("serializing notes: {e}"));
    let want = &case["output"];
    assert_eq!(
        &got_json, want,
        "review mismatch for {file} with options {:?}",
        case["options"]
    );
}

#[test]
fn review_matches_javascript_on_every_case() {
    let fixture: Fixture = load_json(Path::new(REVIEW_FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    for case in &fixture.cases {
        check_review_case(case);
    }
}

#[test]
fn review_oracle_fixture_is_current() {
    assert_oracle_current(REVIEW_ORACLE, REVIEW_FIXTURE);
}

// ---- engine choice ----

fn default_engine_opts(opts: &Value) -> DefaultEngineOpts<'_> {
    DefaultEngineOpts {
        voice: text(opts, "voice"),
        reference: text(opts, "reference"),
        language: text(opts, "language"),
    }
}

/// The skill's own message for [`default_engine`]'s error, rebuilt from
/// the case's own `language` input: the CLI-flavored `speak --language
/// …:` prefix the port leaves out of [`Error::InvalidArgument`].
fn default_engine_message(language: &str, reason: &str) -> String {
    format!("speak --language {language}: {reason}")
}

fn check_default_engine_case(case: &Value) {
    let opts = &case["input"]["opts"];
    let readiness = &case["input"]["readiness"];
    let ok = readiness["ok"]
        .as_bool()
        .unwrap_or_else(|| panic!("case {case} readiness.ok is not a bool"));
    let why = text(readiness, "why").unwrap_or_else(|| panic!("case {case} has no readiness.why"));
    let got = default_engine(&default_engine_opts(opts), ok, why);
    let output = &case["output"];
    if let Some(want) = output.as_str() {
        let got = got.unwrap_or_else(|e| panic!("default_engine({case}): {e}"));
        assert_eq!(
            got,
            match want {
                "kokoro" => Engine::Kokoro,
                "voxcpm" => Engine::Voxcpm,
                other => panic!("fixture names an unknown engine {other:?}"),
            },
            "default_engine, case {case}"
        );
    } else {
        let want_error = text(output, "error")
            .unwrap_or_else(|| panic!("case {case} has neither a string nor an error output"));
        let language = text(opts, "language")
            .unwrap_or_else(|| panic!("case {case} has no language to build its error message"));
        let err = got
            .err()
            .unwrap_or_else(|| panic!("default_engine({case}) unexpectedly succeeded"));
        assert_eq!(
            default_engine_message(language, &reason(err)),
            want_error,
            "default_engine error, case {case}"
        );
    }
}

/// A case's `speed` field: a plain JSON number, or the string `"NaN"` for
/// a case whose JavaScript input is `Number.NaN` (JSON has no literal for
/// it, and `Number("NaN")` coerces the same way `speak()` does).
fn case_speed(v: &Value) -> Option<f64> {
    match &v["speed"] {
        Value::String(s) if s == "NaN" => Some(f64::NAN),
        other => other.as_f64(),
    }
}

fn speak_opts(input: &Value) -> SpeakOpts<'_> {
    let opts = &input["opts"];
    SpeakOpts {
        engine: text(opts, "engine"),
        command: text(opts, "command"),
        model: text(opts, "model"),
        voice: text(opts, "voice"),
        reference: text(opts, "reference"),
        language: text(opts, "language"),
        speed: case_speed(opts),
        stretched: opts["stretched"].as_bool().unwrap_or(false),
        lines: opts["lines"].as_bool().unwrap_or(false),
    }
}

fn tts_config(input: &Value) -> TtsConfig<'_> {
    let tts = &input["tts"];
    TtsConfig {
        engine: text(tts, "engine"),
        command: text(tts, "command"),
        model: text(tts, "model"),
        voice: text(tts, "voice"),
        speed: tts["speed"].as_f64(),
    }
}

/// The skill's own message for the invalid `--engine` or `--speed`
/// errors `resolve_speak` raises, rebuilt from the case's own input: the
/// CLI-flavored prefix the port leaves out of [`Error::InvalidArgument`].
fn resolve_error_message(input: &Value, reason_text: &str) -> Option<String> {
    let opts = &input["opts"];
    if reason_text.starts_with("Kokoro speaks English only") {
        let language = text(opts, "language")?;
        return Some(format!("speak --language {language}: {reason_text}"));
    }
    if reason_text.starts_with("use kokoro or voxcpm") {
        let engine = text(opts, "engine")?;
        return Some(format!("speak --engine \"{engine}\": {reason_text}"));
    }
    if reason_text.starts_with("use 0.5 to 2") {
        let speed = case_speed(opts).unwrap_or(f64::NAN);
        let text = if speed.is_nan() {
            "NaN".to_string()
        } else {
            speed.to_string()
        };
        return Some(format!("speak --speed {text}: {reason_text}"));
    }
    None
}

fn check_resolve_case(case: &Value) {
    let input = &case["input"];
    let script = text(input, "script").unwrap_or_else(|| panic!("case {case} has no script"));
    let readiness = &input["readiness"];
    let ok = readiness["ok"]
        .as_bool()
        .unwrap_or_else(|| panic!("case {case} readiness.ok is not a bool"));
    let why = text(readiness, "why").unwrap_or_else(|| panic!("case {case} has no readiness.why"));
    let opts = speak_opts(input);
    let tts = tts_config(input);
    let got = resolve_speak(script, &opts, &tts, ok, why);
    let output = &case["output"];
    if let Some(want_error) = output["error"].as_str() {
        let err = got
            .err()
            .unwrap_or_else(|| panic!("resolve_speak({case}) unexpectedly succeeded"));
        let reason_text = reason(err);
        let full = resolve_error_message(input, &reason_text)
            .unwrap_or_else(|| panic!("case {case} error {reason_text:?} matches no known prefix"));
        assert_eq!(full, want_error, "resolve_speak error, case {case}");
    } else {
        let r = got.unwrap_or_else(|e| panic!("resolve_speak({case}): {e}"));
        let want = output;
        match &r.engine {
            EngineChoice::Voxcpm { voice } => {
                assert_eq!(want["branch"], "voxcpm", "case {case}");
                assert_eq!(Some(voice.as_str()), want["voice"].as_str(), "case {case}");
            }
            EngineChoice::Command { command } => {
                assert_eq!(want["branch"], "command", "case {case}");
                assert_eq!(
                    Some(command.as_str()),
                    want["command"].as_str(),
                    "case {case}"
                );
            }
            EngineChoice::Kokoro { model, voice } => {
                assert_eq!(want["branch"], "model", "case {case}");
                assert_eq!(Some(model.as_str()), want["model"].as_str(), "case {case}");
                assert_eq!(Some(voice.as_str()), want["voice"].as_str(), "case {case}");
                assert_eq!(want["kokoroModel"], true, "case {case}");
            }
            EngineChoice::Model { model } => {
                assert_eq!(want["branch"], "model", "case {case}");
                assert_eq!(Some(model.as_str()), want["model"].as_str(), "case {case}");
                assert_eq!(want["kokoroModel"], false, "case {case}");
            }
        }
        assert_eq!(want["speed"].as_f64(), Some(r.speed), "speed, case {case}");
        assert_eq!(
            want["strippedTags"].as_bool(),
            Some(r.strip_tags),
            "strippedTags, case {case}"
        );
        assert_eq!(
            want["loggedNotice"].as_bool(),
            Some(r.log_tag_notice),
            "loggedNotice, case {case}"
        );
    }
}

#[test]
fn engine_choice_matches_javascript_on_every_case() {
    let fixture: Fixture = load_json(Path::new(ENGINE_FIXTURE));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");
    for case in &fixture.cases {
        match text(case, "fn") {
            Some("defaultEngine") => check_default_engine_case(case),
            Some("resolveSpeak") => check_resolve_case(case),
            other => panic!("fixture names an unknown function {other:?}"),
        }
    }
}

#[test]
fn engine_choice_oracle_fixture_is_current() {
    assert_oracle_current(ENGINE_ORACLE, ENGINE_FIXTURE);
}
